;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================


p_banner_c:		; call banner (normal)
			pop hl			; text
			ld de, var_banner_text
			ld b, 255
p_banner_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_banner_si0_e
			inc hl
			inc de
			djnz p_banner_si0
			xor a
			ld (de), a
p_banner_si0_e:
			ld (p_banner_rs), sp
			ld sp, p_banner
			jp ntc_xn
p_banner_r:		; end of banner
			ld sp, (p_banner_rs)
			jp ntc_xn
p_level1_play_c:		; call play (normal)
			pop hl			; score
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_level1_play_score), de
			ld hl, 0
			ld (var_level1_play_play), hl
			ld hl, 0
			ld (var_level1_play_i), hl
			ld (p_level1_play_rs), sp
			ld hl, ovl_blk_level1	; page OVERLAYS.001
			ld de, p_level1_play_pg
			ld ix, p_level1_play_in
			jp ntc_ovl_enter
p_level1_play_in:
			ld sp, p_level1_play
			jp ntc_xn
p_level1_play_r:		; end of play
			ld sp, (ntc_csp)		; the caller's page back
			ld hl, (p_level1_play_pg)
			call mem_sel
			ld sp, (p_level1_play_rs)
			jp ntc_xn
p_level1_bonus_c:		; call bonus (normal)
			ld hl, 0
			ld (var_level1_bonus_bonus), hl
			ld (p_level1_bonus_rs), sp
			ld hl, ovl_blk_level1	; page OVERLAYS.001
			ld de, p_level1_bonus_pg
			ld ix, p_level1_bonus_in
			jp ntc_ovl_enter
p_level1_bonus_in:
			ld sp, p_level1_bonus
			jp ntc_xn
p_level1_bonus_r:		; end of bonus
