; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_irq:		jp 6
kw_goto_iffalse_n:	jp 11
kw_next1l_n:	jp 31
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_add:		jp 53
kw_cpeqvl:	jp 96
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl0:	jp 134
kw_printnl:	jp 138
mem_go0:		jp 243
mem_go:		jp 245
mem_sel:		jp 258
mem_pages:	jp 259
mem_ramsize:	jp 261
mem_map:		jp 265
mem_largest:	jp 272
ntc_ovl_enter:	jp 276
ntc_ovl_kunload:	jp 279
ntc_ovl_kloaded:	jp 280
ntc_ovl_kpage:	jp 281
kw_waitkey:	jp 348
NTC_RJ_N	equ 25		; entries
mem_a1	equ #884F		; ROM data
mem_a2	equ #8851		; ROM data
mem_res	equ #8855		; ROM data
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #894E		; ROM data
ntc_v_romen	equ #8954		; ROM data
ntc_v_romold	equ #8956		; ROM data
ntc_v_stamp	equ #8952		; ROM data
ntc_v_start	equ #8950		; ROM data
ovl_kres	equ #888D		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)

; pages (Option Page / Option Class Overlay): the RAM page each is loaded in (0 = not loaded),
; the end of its code and the size of its page variables, its file and its name
ovl_blk_level1:	dw 0, ovl_level1_end, ovl_level1_vsize
			db "OVERLAYS.001", 0, "Level1", 0	; its file, its name (for the messages)
ovl_blk_level2:	dw 0, ovl_level2_end, ovl_level2_vsize
			db "OVERLAYS.002", 0, "Level2", 0	; its file, its name (for the messages)


; the start code (Library: ROM): run once, then the arrays go over it
ntc_rj_drop:
; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			IF (ntc_bss >= 32768) && (ntc_bssfrom <= 16384)	; fwdref-ok
			ld hl, ntc_bssfrom		; (the end of the program - or this start code, which tables may go over)
			ELSE
			ld hl, ntc_free
			ENDIF
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, NTC_STAMP
			ld (ntc_v_stamp), hl
			ld a, 1
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCFW", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCFW<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0
ntc_rj_dropend:
ntc_rg61_e:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
			IF ntc_rj_dropend == ntc_end	; fwdref-ok
ntc_bssfrom	equ ntc_rj_drop		; the arrays over the start code (it has run)
			ELSE
ntc_bssfrom	equ ntc_end
			ENDIF
			IF (ntc_bssfrom < 32768) && (ntc_bssfrom + ntc_bss_size > 16384)	; fwdref-ok
ntc_bss		equ 32768		; after Option Reserve #4000-#7FFF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			IF ntc_free <= 32768	; fwdref-ok
ntc_memtab	equ 32768		; the Memory class's tables: above the window (Option Reserve)
			ELSE
ntc_memtab	equ ntc_free
			ENDIF
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 16384) || (ntc_bss >= 32768), "the program (or its arrays) reaches into Option Reserve #4000-#7FFF (Main.bas line 15)"
			SAVEAMSDOS "OVERLAYS.BIN", ntc_start, ntc_end - ntc_start, ntc_start
			ASSERT (ntc_free <= #4000) || (ntc_start >= #8000), "overlay classes: the program and its arrays must stay out of #4000-#7FFF (the window they run in)"

; ============================================================
; Page Level1 -> OVERLAYS.001: level1 - threads built to run at #4000
; (a RAM page, or the overlay area); their variables are in the program, but for
; Private Paged ones (after the code). Written as its own file.
; ============================================================
			ORG #4000
ovl_level1_start:
			dw NTC_STAMP		; the build stamp: the loader checks it against the program's
ovl_level1__0_s:		; level1
p_level1_play:

			; Level1.cls 4: Dim i As Integer

			; Level1.cls 5: Banner "Level 1"
			dw p_banner_c, str16

			; Level1.cls 6: For i = 1 To 3
			dw kw_ltov, 1, var_level1_play_i
for4_t:

			; Level1.cls 7: Print "  room "; i
			dw kw_printstrvar, str17
			dw kw_printint, var_level1_play_i
			dw kw_printnl

			; Level1.cls 8: Next
			dw kw_next1l_n, var_level1_play_i, 3, for4_t
for4_e:

			; Level1.cls 9: Play = 100
			dw kw_ltov, 100, var_level1_play_play
			dw p_level1_play_r
p_level1_bonus:

			; Level1.cls 12: Bonus = 50
			dw kw_ltov, 50, var_level1_bonus_bonus
			dw p_level1_bonus_r
ovl_level1__0_e:
			dw 0			; (never empty)
ovl_level1_end:		; the end of its file; page variables (cleared on loading) follow
ovl_level1_vsize	equ 0		; its page variables; its local memory is the rest, to #8000
			ASSERT ovl_level1_end + ovl_level1_vsize <= #8000, "page Level1 (level1) is more than 16K (code and page variables)"
			DISPLAY "page Level1 (OVERLAYS.001):"
			DISPLAY "  level1 ", /D, ovl_level1__0_e - ovl_level1__0_s
			DISPLAY "  page variables ", /D, ovl_level1_vsize, ", free ", /D, #8000 - (ovl_level1_end + ovl_level1_vsize)
			SAVEAMSDOS "OVERLAYS.001", ovl_level1_start, ovl_level1_end - ovl_level1_start, #4000

; ============================================================
; Page Level2 -> OVERLAYS.002: level2 - threads built to run at #4000
; (a RAM page, or the overlay area); their variables are in the program, but for
; Private Paged ones (after the code). Written as its own file.
; ============================================================
			ORG #4000
ovl_level2_start:
			dw NTC_STAMP		; the build stamp: the loader checks it against the program's
ovl_level2__0_s:		; level2
p_level2_play:

			; Level2.cls 5: Banner "Level 2"
			dw p_banner_c, str18

			; Level2.cls 6: Print "  score so far "; score; ", level 1 loaded "; Level1.Loaded()
			dw kw_printstrvar, str19
			dw kw_printint, var_level2_play_score
			dw fn_level1_loaded, var_level1_loaded_loaded
			dw kw_printstrvar, str20
			dw kw_printint, var_level1_loaded_loaded
			dw kw_printnl

			; Level2.cls 7: Print "  bonus from level 1 "; Level1.Bonus()
			dw p_level1_bonus_c
			dw kw_printstrvar, str21
			dw kw_printint, var_level1_bonus_bonus
			dw kw_printnl

			; Level2.cls 8: Play = 250
			dw kw_ltov, 250, var_level2_play_play
			dw p_level2_play_r
ovl_level2__0_e:
			dw 0			; (never empty)
ovl_level2_end:		; the end of its file; page variables (cleared on loading) follow
ovl_level2_vsize	equ 0		; its page variables; its local memory is the rest, to #8000
			ASSERT ovl_level2_end + ovl_level2_vsize <= #8000, "page Level2 (level2) is more than 16K (code and page variables)"
			DISPLAY "page Level2 (OVERLAYS.002):"
			DISPLAY "  level2 ", /D, ovl_level2__0_e - ovl_level2__0_s
			DISPLAY "  page variables ", /D, ovl_level2_vsize, ", free ", /D, #8000 - (ovl_level2_end + ovl_level2_vsize)
			SAVEAMSDOS "OVERLAYS.002", ovl_level2_start, ovl_level2_end - ovl_level2_start, #4000

NTC_STAMP	equ #74E3		; the build stamp: the first word of every page file
